static lstr L2082 = {-1, 5, "E1000"};
static lstr L2083 = {-1, 68, "@%s is not written on a function of an extern block; only @extern is"};
static lstr L2084 = {-1, 5, "E1000"};
static lstr L2085 = {-1, 56, "an extern block holds only function signatures, found %s"};
static lstr L2086 = {-1, 5, "E1000"};
static lstr L2087 = {-1, 54, "%s in an extern block cannot be generic or a generator"};
static lstr L2088 = {-1, 5, "E1000"};
